246:   template <typename SrcType, typename DstType>
247:   void copyVector(const std::byte* src, size_t count, std::vector<DstType>& dest) {
248:     if constexpr (std::is_convertible_v<SrcType, DstType>) {
249:       if (sizeof(DstType) < sizeof(SrcType)) {
250:         throw std::runtime_error("Destination type size is smaller than source type size");
251:       }
252:       dest.resize(count);
253:       const SrcType* srcPtr = reinterpret_cast<const SrcType*>(src);
254:       for (size_t i = 0; i < count; ++i) {
255:         dest[i] = static_cast<DstType>(srcPtr[i]);
256:       }
257:     } else {
258:       throw std::runtime_error("Source type is not convertible to destination type");
259:     }
260:   }
261: 
262:   template <typename DstType>
263:   void copyVector(Type type, const std::byte* src, size_t count, std::vector<DstType>& dest) {
264:     dispatchType(type, [&]<Type type>() {
265:       copyVector<TypeTraits_t<type>, DstType>(src, count, dest);
266:     });
267:   }
