269:   // Utility functions for byte order conversion
270:   template <typename T>
271:   inline T swap(T val) {
272:     if constexpr (std::is_same_v<T, Rational> || std::is_same_v<T, SRational>) {
273:       return { std::byteswap(val.numerator), std::byteswap(val.denominator) };
274:     } else if constexpr (std::is_same_v<T, float>) {
275:       uint32_t u32;
276:       std::memcpy(&u32, &val, sizeof(u32));
277:       u32 = std::byteswap(u32);
278:       std::memcpy(&val, &u32, sizeof(val));
279:       return val;
280:     } else if constexpr (std::is_same_v<T, double>) {
281:       uint64_t u64;
282:       std::memcpy(&u64, &val, sizeof(u64));
283:       u64 = std::byteswap(u64);
284:       std::memcpy(&val, &u64, sizeof(val));
285:       return val;
286:     } else if constexpr (std::is_same_v<T, Tag>) {
287:       const auto value = static_cast<std::underlying_type_t<Tag>>(val);
288:       return static_cast<Tag>(std::byteswap(value));
289:     } else if constexpr (std::is_same_v<T, Type>) {
290:       const auto value = static_cast<std::underlying_type_t<Type>>(val);
291:       return static_cast<Type>(std::byteswap(value));
292:     } else if constexpr (sizeof(T) > 1) {
293:       return std::byteswap(val);
294:     }
295:     else {
296:       return val; // No swap needed single byte
297:     }
298:   }
