314:   // Helper functions for working with streams
315:   template <typename T>
316:   std::istream& readValue(std::istream& stream, T& value, bool mustSwap = false) {
317:     if (!stream) {
318:       throw std::runtime_error("Stream is not valid for reading");
319:     }
320:     stream.read(reinterpret_cast<char*>(&value), sizeof(value));
321:     if (mustSwap) {
322:       value = swap(value);
323:     }
324:     return stream;
325:   }
326: 
327:   template <typename T>
328:   T readValue(std::istream& stream, bool mustSwap = false) {
329:     T value;
330:     readValue(stream, value, mustSwap);
331:     return value;
332:   }
