599:       const Entry& getEntry(Tag tag,
600:         std::string errorMessage = "Entry not found") const {
601:         auto it = entries_.find(tag);
602:         if (it == entries_.end()) {
603:           throw std::runtime_error(errorMessage);
604:         }
605:         return it->second;
