608:       static IFD read(std::istream& stream, bool mustSwap = false) {
609:         IFD ifd;
610: 
611:         // Read the number of entries
612:         uint16_t entryCount = readValue<uint16_t>(stream, mustSwap);
613: 
614:         // Read each entry
615:         Tag lastTag = Tag::Null;
616:         for (uint16_t i = 0; i < entryCount; ++i) {
617:           Entry entry = Entry::read(stream, mustSwap);
618:           ifd.entries_[entry.tag()] = std::move(entry);
619:           if (entry.tag() <= lastTag) {
620:             throw std::runtime_error("Entries must be sorted by tag in ascending order");
621:           }
622:           lastTag = entry.tag();
623:         }
624: 
625:         return ifd;
