654:     static TiffImage read(std::istream& stream) {
655:       TiffImage image;
656: 
657:       // Read and parse the header
658:       image.header_ = Header::read(stream);
659: 
660:       // Read the IFDs
661:       const bool mustSwap = !image.header_.equalsHostByteOrder();
662:       std::set<uint32_t> visited;
663:       uint32_t offset = image.header_.firstIFDOffset();
664:       while (offset > 0) {
665:         if (!visited.insert(offset).second) {
666:           throw std::runtime_error("Cyclic IFD offset detected in TIFF file");
667:         }
668:         // Seek to the IFD offset
669:         stream.seekg(offset);
670:         if (stream.fail()) {
671:           throw std::runtime_error("Failed to seek to IFD offset");
672:         }
673: 
674:         // Read the IFD
675:         TiffImage::IFD ifd = TiffImage::IFD::read(stream, mustSwap);
676:         image.ifds_.push_back(std::move(ifd));
677: 
678:         // Read the next IFD offset
679:         offset = readValue<uint32_t>(stream, mustSwap);
680:       }
681: 
682:       return image;
683:     }
