410:     // Header class
411:     // ============
412:     // A TIFF file begins with an 8-byte image file header:
413:     // - Bytes 0-1: The byte order used within the file. Legal values are:
414:     //   - “II” (4949.H)
415:     //   - “MM” (4D4D.H)
416:     //   In the “II” format, byte order is always from the least significant
417:     //   byte to the most significant byte, for both 16-bit and 32-bit integers
418:     //   This is called little-endian byte order. In the “MM” format, byte order
419:     //   is always from most significant to least significant, for both 16-bit
420:     //   and 32-bit integers. This is called big-endian byte order.
421:     // - Bytes 2-3 An arbitrary but carefully chosen number (42) that further
422:     //   identifies the file as a TIFF file. The byte order depends on the value
423:     //   of Bytes 0-1.
424:     // - Bytes 4-7 The offset (in bytes) of the first IFD. The directory may be
425:     //   at any location in the file after the header but must begin on a word
426:     //   boundary.
427:     class Header {
428:       std::endian byteOrder_;
429:       uint32_t firstIFDOffset_;
430:     public:
431:       std::endian byteOrder() const { return byteOrder_; }
432: 
433:       bool equalsHostByteOrder() const {
434:         return std::endian::native == byteOrder_;
435:       }
436: 
437:       uint32_t firstIFDOffset() const { return firstIFDOffset_; }
438: 
439:       static Header read(std::istream& stream) {
440:         Header header;
441: 
442:         // Byte order
443:         uint16_t byteOrder = readValue<uint16_t>(stream); // 0x4949 for "II", 0x4D4D for "MM"
444:         if (byteOrder != 0x4949 && byteOrder != 0x4D4D) {
445:           throw std::runtime_error("Invalid byte order in TIFF header");
446:         }
447:         header.byteOrder_ =
448:           (byteOrder == 0x4949) ? std::endian::little : std::endian::big;
449: 
450:         // Swap byte order if necessary
451:         const bool mustSwap = !header.equalsHostByteOrder();
452: 
453:         // Magic number
454:         uint16_t magicNumber = readValue<uint16_t>(stream, mustSwap);
455:         if (magicNumber != 42) {
456:           throw std::runtime_error("Invalid magic number in TIFF header");
457:         }
458: 
459:         // First IFD offset
460:         uint32_t firstIFDOffset = readValue<uint32_t>(stream, mustSwap);
461:         if (firstIFDOffset < 8) { // Minimum size of TIFF header
462:           throw std::runtime_error("Invalid first IFD offset in TIFF header");
463:         }
464:         header.firstIFDOffset_ = firstIFDOffset;
465: 
466:         return header;
467:       }
468:     };
