165:     // Copies the values from a TIFF entry to a vector of integers.
166:     template <typename T>
167:     static std::vector<int> makeIntVec(const TiffImage::IFD::Entry& entry)
168:     {
169:       std::vector<int> v(entry.count());
170:       const auto* values = reinterpret_cast<const T*>(entry.values());
171:       for (size_t i = 0; i < entry.count(); ++i) {
172:         if constexpr (is_rational_v<T>) {
173:           if (values[i].denominator == 0) {
174:             throw std::runtime_error("Rational value with zero denominator in TIFF entry");
175:           }
176:           v[i] = static_cast<int>(values[i].numerator / values[i].denominator);
177:         }
178:         else {
179:           v[i] = static_cast<int>(values[i]);
180:         }
181:       }
182:       return v;
183:     }
