113: // This function takes an exporter as template parameter and a list of files.
114: // The list of files must be set in pairs: first a TIFF file to test, then a
115: // PPM, PGM, or PBM file to compare against.
116: template <typename Exporter>
117: void TestExporter(const std::vector<std::string>& testFiles)
118: {
119:   if (testFiles.size() % 2 != 0) {
120:     throw std::runtime_error("Test files must be in pairs.");
121:   }
122:   LoadParams loadParams{ 0 };
123:   Exporter exporter;
124:   for (size_t i = 0; i < testFiles.size() / 2; ++i) {
125:     const auto tiffFilePath = getFilePath(testFiles[2*i + 0]);
126:     const auto refFilePath = getFilePath(testFiles[2*i + 1]);
127:     INFO(("Test file: " + tiffFilePath.string()));
128:     INFO(("Reference file: " + refFilePath.string()));
129:     load(tiffFilePath.string(), std::ref(exporter), loadParams);
130: 
131:     const auto& image = exporter.image();
132: 
133:     try { // Gray 8bits
134:       compareToReference<uint8_t>(image, refFilePath);
135:       return;
136:     } catch (const std::exception& ex) { /* ignore */ }
137: 
138:     try { // Gray 16bits
139:       compareToReference<uint16_t>(image, refFilePath, 1);
140:       return;
141:     } catch (const std::exception& ex) { /* ignore */ }
142: 
143:     try { // Gray 32bits
144:       compareToReference<uint32_t>(image, refFilePath);
145:       return;
146:     } catch (const std::exception& ex) { /* ignore */ }
147: 
148:     try { // RGB 8bits
149:       compareToReference<netpbm::RGB8>(image, refFilePath, 1);
150:       return;
151:     } catch (const std::exception& ex) { /* ignore */ }
152: 
153:     try { // RGB 16bits
154:       compareToReference<netpbm::RGB16>(image, refFilePath, 1);
155:       return;
156:     } catch (const std::exception& ex) { /* ignore */ }
157: 
158:     try { // RGB 32bits
159:       compareToReference<netpbm::RGB32>(image, refFilePath);
160:       return;
161:     } catch (const std::exception& ex) { /* ignore */ }
162: 
163:     try { // Bitmap 1bit
164:       compareToReference<bool>(image, refFilePath);
165:       return;
166:     } catch (const std::exception& ex) { /* ignore */ }
167: 
168:     FAIL(("Unsupported reference file format: " + refFilePath.string()));
169:   }
170: }
